# core/page_setup.py

"""
Єдиний «старт сторінки» та футер (правки К6, К4).

Раніше кожна з 13 сторінок повторювала однаковий блок:
конфіг сторінки → логотип → CSS → авторизація → меню → перевірка доступу,
а футер із зашитою версією був скопійований у 10 файлах.

Тепер сторінка починається одним викликом:

    from core.page_setup import page_setup, render_footer
    current_user = page_setup("Dashboard", page_name="Dashboard")
    ...
    render_footer()
"""

from __future__ import annotations

import streamlit as st

from core.errors import log_cosmetic_error
from core.config import APP_VERSION
from core.theme import inject_theme, apply_plotly_theme
from core.ui import load_css
from core.auth import init_auth_state, render_login_form
from core.navigation import render_role_page_links, require_page_access

_LOGO_B64 = (
    ""
)


def _render_sidebar_logo() -> None:
    """Логотип Мінекономіки як перший елемент усередині бічної панелі.

    Свідомо НЕ використовуємо st.logo(): він кладе зображення у верхню
    службову смужку з фіксованим маленьким розміром, і його не можна
    розтягнути на всю ширину панелі. Тут логотип малюється власною
    розміткою прямо в тіло sidebar, тому автоматично:
      • займає всю ширину панелі й розтягується разом із нею;
      • зникає разом із панеллю, коли її згорнуто (він фізично всередині).
    """
    st.sidebar.markdown(
        '<div data-mineco-logo="true">'
        f'<img src="data:image/png;base64,{_LOGO_B64}" alt="Мінекономіки" />'
        "</div>",
        unsafe_allow_html=True,
    )


def _hide_streamlit_fixed_chrome() -> None:
    """Прибирає лише нижню службову sticky-область Streamlit.

    Верхній ``stHeader`` навмисно не модифікується CSS-ом. У Streamlit 1.59.x
    саме верхній chrome відповідає, зокрема, за системні елементи керування
    бічною панеллю. Попередня реалізація приховувала ``stToolbar`` і вимикала
    ``pointer-events`` для всього header, а потім намагалася точково повернути
    кнопку sidebar через внутрішні ``data-testid``. Така прив'язка крихка:
    при зміні DOM кнопка розгортання може зникнути разом із батьківським
    контейнером.

    Зайві елементи верхнього меню тепер прибираються штатною конфігурацією
    ``client.toolbarMode = "minimal"`` у ``.streamlit/config.toml``.
    Тут залишається тільки очищення нижньої sticky-області та її spacer.
    Наш власний футер ``.app-footer`` не зачіпається.
    """
    st.markdown(
        """
        <style>
        /*
         * Нижня sticky-область Streamlit. Селектори без прив'язки до типу
         * HTML-тега залишаються працездатними при внутрішніх змінах розмітки.
         */
        [data-testid="stBottom"],
        [data-testid="stBottomBlockContainer"],
        [data-testid="stBottomContainer"],
        .stBottom,
        .stBottomBlockContainer {
            display: none !important;
            visibility: hidden !important;
            position: static !important;
            width: 0 !important;
            height: 0 !important;
            min-width: 0 !important;
            min-height: 0 !important;
            max-height: 0 !important;
            padding: 0 !important;
            margin: 0 !important;
            overflow: hidden !important;
        }

        /*
         * Streamlit 1.59.x додає перед stBottom окремий flex-spacer без
         * data-testid. :has() точно знаходить тільки spacer, що безпосередньо
         * передує нижньому контейнеру, і не зачіпає звичайний контент сторінки.
         */
        [data-testid="stMain"] > div:not([data-testid]):has(+ [data-testid="stBottom"]) {
            display: none !important;
            visibility: hidden !important;
            flex: 0 0 0 !important;
            flex-grow: 0 !important;
            width: 0 !important;
            height: 0 !important;
            min-height: 0 !important;
            max-height: 0 !important;
            padding: 0 !important;
            margin: 0 !important;
        }

        /* Захисний варіант для розмітки, де spacer має службовий клас. */
        [data-testid="stMain"] > [class*="AppViewBlockSpacer"],
        [data-testid="stMain"] > [class*="BlockSpacer"]:has(+ [data-testid="stBottom"]) {
            display: none !important;
            flex: 0 0 0 !important;
            height: 0 !important;
            min-height: 0 !important;
            padding: 0 !important;
            margin: 0 !important;
        }

        /* Після приховування нижньої службової області не лишаємо відступів. */
        div.block-container,
        .main .block-container,
        [data-testid="stMainBlockContainer"] {
            padding-top: 1rem !important;
            padding-bottom: 1rem !important;
        }

        [data-testid="stAppViewContainer"] > .main,
        section.main,
        [data-testid="stMain"] {
            padding-bottom: 0 !important;
            margin-bottom: 0 !important;
        }

        /*
         * Логотип Мінекономіки всередині бічної панелі.
         * Малюється власною розміткою (_render_sidebar_logo) як перший
         * елемент sidebar, тому розтягується на всю ширину панелі й
         * зникає разом із нею. Ховаємо старий слот st.logo у верхній
         * смужці, щоб логотип не дублювався.
         */
        [data-testid="stSidebarHeader"] [data-testid="stLogo"],
        [data-testid="stHeader"] [data-testid="stLogo"],
        [data-testid="stSidebarHeader"] a[data-testid="stLogoLink"],
        [data-testid="stHeader"] a[data-testid="stLogoLink"] {
            display: none !important;
        }

        section[data-testid="stSidebar"] div[data-mineco-logo="true"] {
            box-sizing: border-box !important;
            width: 100% !important;
            margin: 0 0 8px 0 !important;
            padding: 0 !important;
        }

        section[data-testid="stSidebar"] div[data-mineco-logo="true"] img {
            display: block !important;
            width: 100% !important;
            height: auto !important;
            margin: 0 !important;
            padding: 0 !important;
            object-fit: contain !important;
        }

        /*
         * Логотип має стояти в самому верху панелі. Службова шапка sidebar
         * (stSidebarHeader) над ним має власну висоту, паддінги і резервує
         * місце під кнопку згортання — усе це стискаємо до нуля. Логотип
         * додатково підтягуємо вгору невеликим негативним відступом, щоб він
         * сів упритул до верхнього краю панелі.
         */
        section[data-testid="stSidebar"] [data-testid="stSidebarHeader"] {
            padding: 0 !important;
            margin: 0 !important;
            min-height: 0 !important;
            height: auto !important;
        }

        section[data-testid="stSidebar"] > div:first-child,
        section[data-testid="stSidebar"] [data-testid="stSidebarUserContent"] {
            padding-top: 0 !important;
            margin-top: 0 !important;
        }

        section[data-testid="stSidebar"] div[data-mineco-logo="true"] {
            margin-top: -8px !important;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )


def page_setup(page_title: str, page_name: str | None = None,
               layout: str = "wide", stop_if_no_access: bool = True):
    """
    Виконує стандартний старт сторінки. Повертає поточного користувача.

    page_name — назва вкладки в системі доступів (config/roles.ROLE_PAGES);
    якщо не передано, перевірка доступу не виконується (для app.py доступ
    відкритий усім ролям).

    ВАЖЛИВО: кнопку "Переглянути загальну інформацію" тут більше НЕ
    малюємо автоматично — за фідбеком вона має стояти поруч із кнопкою
    "Скинути фільтри" (як на app.py), а не окремим блоком угорі сторінки.
    Кожна сторінка викликає core.ui.render_scope_toggle(page_name, current_user)
    сама, у потрібному місці — поруч зі своїми фільтрами.
    """
    st.set_page_config(
        page_title=page_title,
        layout=layout,
        initial_sidebar_state="expanded",
    )

    try:
        _render_sidebar_logo()
    except Exception as exc:
        log_cosmetic_error("Відображення логотипа в сайдбарі", exc)

    load_css()
    _hide_streamlit_fixed_chrome()
    inject_theme()
    apply_plotly_theme()

    init_auth_state()
    current_user = render_login_form()
    render_role_page_links()

    if page_name and not require_page_access(page_name):
        if stop_if_no_access:
            st.stop()

    return current_user


def render_footer() -> None:
    """Єдиний футер системи. Версія береться з core.config.APP_VERSION."""
    st.markdown(
        f"""
        <div class="app-footer">
            <strong>Розроблено департаментом стратегічного планування
            та макроекономічного прогнозування</strong><br>
            Версія {APP_VERSION} | 2026 | Внутрішня система моніторингу стратегічного плану
        </div>
        """,
        unsafe_allow_html=True,
    )
